UPDATE lessons SET title='Year 4, Week 21, Lesson 1: Units of length: mm, cm, m and km', data=json_patch(data,'{"child_mission":"Length units relate by place-value style scales: 10 mm = 1 cm; 100 cm = 1 m; 1000 m = 1 km.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same method to a larger number or a new context, then compare two solution paths for accuracy.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nWhich unit suits: width of a fingernail; length of a soccer field; distance between cities?\n\nFEEDBACK\nmm (or cm); m; km.\n\nWATCH FOR\nMeasuring a playground in millimetres alone creates huge, hard-to-read numbers.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nSort twenty objects/distances into best units (mm/cm/m/km) and write five conversion facts from memory.\n\nWrite a short reflection naming one step you corrected and why.","interactive_activities":null,"learning_area":"Mathematics","learning_intention":"Length units relate by place-value style scales: 10 mm = 1 cm; 100 cm = 1 m; 1000 m = 1 km.","lesson_number":1,"lesson_role":"Concept","materials":["Paper or typed answer space","Pencil","Optional: place-value chart or number line"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["MA2-GM-01"],"parent_notes":"Parent: Marking guidance for the independent task: Sort twenty objects/distances into best units (mm/cm/m/km) and write five conversion facts from memory. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: new numbers solved with visible working for millimetre; key places/values named. Do not award marks for retyping the model.\n\nParent: Written mod